@Service
public class TransportAlerts {
 @org.springframework.beans.factory.annotation.Autowired private com.example.eac_backend_project.repository.transport.VehicleRepository fleet;
 private final TransportNotifications notifications;private final TransportPolicies policies;private final TransportPolicyService policyService;private final TransportVehicleProfiles vehicles;private final TransportDriverProfiles drivers;private final UserRepository users;private final TransportAccess access;private final JavaMailSender mail;private final UserService accounts;private final TransactionTemplate tx;
 private final Map<Long,Instant> testLimits=new ConcurrentHashMap<>();
 @Value("${spring.mail.username:}") private String sender;
 @Value("${app.frontend.base-url:http://localhost:5173}") private String frontend;
 @Value("${transport.mail.timeout-ms:10000}") private int mailTimeout;
 private JavaMailSender boundedSender(){if(!(mail instanceof org.springframework.mail.javamail.JavaMailSenderImpl configured))return mail;var sender=new org.springframework.mail.javamail.JavaMailSenderImpl();sender.setHost(configured.getHost());sender.setPort(configured.getPort());sender.setProtocol(configured.getProtocol());sender.setUsername(configured.getUsername());sender.setPassword(configured.getPassword());sender.setDefaultEncoding("UTF-8");var properties=new Properties();properties.putAll(configured.getJavaMailProperties());String timeout=Integer.toString(Math.max(1000,Math.min(60000,mailTimeout)));for(String protocol:List.of("smtp","smtps"))for(String option:List.of("connectiontimeout","timeout","writetimeout"))properties.setProperty("mail."+protocol+"."+option,timeout);sender.setJavaMailProperties(properties);return sender;}
 public TransportAlerts(TransportNotifications notifications,TransportPolicies policies,TransportPolicyService policyService,TransportVehicleProfiles vehicles,TransportDriverProfiles drivers,UserRepository users,TransportAccess access,JavaMailSender mail,UserService accounts,PlatformTransactionManager manager){this.notifications=notifications;this.policies=policies;this.policyService=policyService;this.vehicles=vehicles;this.drivers=drivers;this.users=users;this.access=access;this.mail=mail;this.accounts=accounts;this.tx=new TransactionTemplate(manager);}
 @Transactional
 public void event(Vehicles vehicle,String type,String title,String body,String reference,String path,String dedupe,Collection<User> extra){
  if(vehicle!=null)fleet.lock(vehicle.getId()).orElseThrow(()->fail(404,"Vehicle unavailable"));
  TransportPolicy policy=policyService.policy();Set<User> recipients=new LinkedHashSet<>();
  if(extra!=null)recipients.addAll(extra);
  if(policy.notifyAdmin)users.findByEnabledTrue().stream().filter(access::admin).forEach(recipients::add);
  if(vehicle!=null&&policy.notifyDriver)vehicles.findByVehicle_Id(vehicle.getId()).filter(p->p.driver!=null).flatMap(p->drivers.findByDriver_Id(p.driver.getId())).filter(p->p.active&&p.notificationsEnabled&&p.account!=null&&Boolean.TRUE.equals(p.account.getEnabled())).map(p->p.account).ifPresent(recipients::add);
  Set<String> addresses=new HashSet<>();
  for(User recipient:recipients){if(!Boolean.TRUE.equals(recipient.getEnabled()))continue;String address=recipient.getEmail();var preference=drivers.findByAccount_Id(recipient.getId());if(preference.isPresent()&&!access.admin(recipient)){if(!preference.get().active||!preference.get().notificationsEnabled)continue;if(preference.get().email!=null)address=preference.get().email;}addresses.add(Objects.toString(address,"").toLowerCase(Locale.ROOT));create(vehicle,recipient,address,type,title,body,reference,path,dedupe+":user:"+recipient.getId(),policy.inAppEnabled,policy.emailEnabled);}
  LinkedHashSet<String> configured=new LinkedHashSet<>(policy.notifyAdmin?TransportPolicyService.split(policy.adminEmails):List.of());
  if(type.startsWith("FAULT"))configured.addAll(TransportPolicyService.split(policy.faultEmails));
  if(type.startsWith("PROCUREMENT"))configured.addAll(TransportPolicyService.split(policy.procurementEmails));
  if(type.startsWith("MAINTENANCE"))configured.addAll(TransportPolicyService.split(policy.supervisorEmails));
  if(type.equals("FAULT_CRITICAL")&&policy.criticalEscalation)configured.addAll(TransportPolicyService.split(policy.escalationEmails));
  for(String address:configured)if(addresses.add(address.toLowerCase(Locale.ROOT)))create(vehicle,null,address,type,title,body,reference,path,dedupe+":email:"+address.toLowerCase(Locale.ROOT),false,policy.emailEnabled);
 }
 private void create(Vehicles vehicle,User user,String address,String type,String title,String body,String reference,String path,String key,boolean inApp,boolean emailEnabled){String dedupe=hash(key);if(notifications.existsByDedupeKey(dedupe))return;TransportNotification n=new TransportNotification();n.vehicle=vehicle;n.recipient=user;n.email=address;n.eventType=type;n.title=title;n.body=body;n.reference=reference;n.targetPath=path;n.dedupeKey=dedupe;n.inApp=inApp&&user!=null;n.emailEnabled=emailEnabled&&address!=null&&!address.isBlank();n.deliveryStatus=n.emailEnabled?"PENDING":"DISABLED";n.priority=type.contains("CRITICAL")?"CRITICAL":type.contains("OVERDUE")||type.contains("EXPIRED")?"HIGH":"NORMAL";notifications.save(n);}
 @Transactional
 public void driverExpiry(TransportDriverProfile driver,long days,int threshold,long period){var p=policyService.policy();String type=days<0?"DRIVER_LICENSE_EXPIRED":"DRIVER_LICENSE_EXPIRY";String key="driver-license:"+driver.driver.getId()+":"+driver.driver.getLicenseExpiry()+":"+threshold+":"+period;String body=driver.driver.getDriverName()+" — licence "+(days<0?"expired "+(-days)+" days ago":days==0?"expires today (valid through today)":"expires in "+days+" days")+". Expiry: "+driver.driver.getLicenseExpiry()+".";event(null,type,"Driver licence expiry",body,"driver:"+driver.driver.getId(),"/drivers",key,p.notifyDriver&&driver.account!=null?List.of(driver.account):List.of());if(p.notifyDriver&&driver.notificationsEnabled&&driver.account==null&&driver.email!=null)create(null,null,driver.email,type,"Driver licence expiry",body,"driver:"+driver.driver.getId(),"/drivers",key+":email:"+driver.email,false,p.emailEnabled);}
 @Transactional
 public void invite(User user){TransportPolicy p=policyService.policy();create(null,user,user.getEmail(),"DRIVER_INVITATION","Set up your EAC driver account","Your driver account is ready. Use the secure setup link in this email to choose your password.","driver-account-"+user.getId(),"/transport/driver", "invite:"+user.getId()+":"+UUID.randomUUID(),p.inAppEnabled,p.emailEnabled);}
 @Transactional(readOnly=true)
 public List<Map<String,Object>> list(boolean deliveryLog){User user=access.current();if(deliveryLog)access.require("TRANSPORT_SETTINGS");var list=deliveryLog?notifications.findByArchivedAtIsNullOrderByCreatedAtDesc():notifications.findByRecipient_IdOrderByCreatedAtDesc(user.getId());return list.stream().filter(n->deliveryLog||n.inApp).limit(500).map(n->describe(n,deliveryLog)).toList();}
 Map<String,Object> describe(TransportNotification n,boolean admin){Map<String,Object> r=row(n);r.putAll(map("eventType",n.eventType,"priority",n.priority,"title",n.title,"body",n.body,"targetPath",n.targetPath,"reference",n.reference,"vehicleId",n.vehicle==null?null:n.vehicle.getId(),"vehicle",n.vehicle==null?null:n.vehicle.getDvla(),"readAt",n.readAt));if(admin)r.putAll(map("email",n.email,"recipient",n.recipient==null?null:n.recipient.getName(),"deliveryStatus",n.deliveryStatus,"attempts",n.attempts,"lastError",n.lastError,"nextAttemptAt",n.nextAttemptAt,"deliveredAt",n.deliveredAt));return r;}
 @Transactional(readOnly=true)
 public Map<String,Object> history(boolean deliveryLog,int page,int size,String type,boolean unreadOnly){if(page<0||size<1||size>100)throw fail(400,"Choose a valid page and a page size between one and 100");User user=access.current();if(deliveryLog)access.require("TRANSPORT_SETTINGS");var source=deliveryLog?notifications.findByArchivedAtIsNullOrderByCreatedAtDesc():notifications.findByRecipient_IdOrderByCreatedAtDesc(user.getId());var visible=source.stream().filter(n->n.archivedAt==null&&(deliveryLog||n.inApp)).toList();long unread=visible.stream().filter(n->n.recipient!=null&&n.recipient.getId().equals(user.getId())&&n.inApp&&n.readAt==null).count();var filtered=visible.stream().filter(n->type==null||type.isBlank()||type.equals(n.eventType)).filter(n->!unreadOnly||n.readAt==null).toList();return map("items",filtered.stream().skip((long)page*size).limit(size).map(n->describe(n,deliveryLog)).toList(),"page",page,"size",size,"total",filtered.size(),"unreadCount",unread,"eventTypes",visible.stream().map(n->n.eventType).distinct().sorted().toList());}
 @Transactional
 public void read(Long id){User user=access.current();TransportNotification n=notifications.lock(id).orElseThrow(()->fail(404,"Notification unavailable"));if(n.recipient==null||!n.recipient.getId().equals(user.getId())||!n.inApp)throw fail(403,"Notification belongs to another account");n.readAt=Instant.now();}
 @Transactional
 public void readAll(){User user=access.current();notifications.findByRecipient_IdOrderByCreatedAtDesc(user.getId()).stream().filter(n->n.inApp&&n.readAt==null).forEach(n->n.readAt=Instant.now());}
 @Transactional
 public void retry(Long id){access.require("TRANSPORT_SETTINGS");TransportNotification n=notifications.lock(id).orElseThrow(()->fail(404,"Delivery unavailable"));if(!Set.of("FAILED","RETRY").contains(n.deliveryStatus))throw fail(409,"Only failed deliveries can be retried");n.deliveryStatus="RETRY";n.attempts=0;n.nextAttemptAt=Instant.now();n.emailEnabled=true;}
 @Transactional
 public Map<String,Object> test(JsonNode data){access.require("TRANSPORT_SETTINGS");User user=access.current();Instant now=Instant.now();Instant previous=testLimits.putIfAbsent(user.getId(),now);if(previous!=null&&previous.isAfter(now.minusSeconds(60)))throw fail(429,"Wait one minute before sending another test email");testLimits.put(user.getId(),now);String to=email(text(data,"email",254,true));TransportNotification n=new TransportNotification();n.email=to;n.recipient=user;n.eventType="SMTP_TEST";n.title="EAC Transport email configuration test";n.body="This is a requested test of your Transport email configuration.";n.targetPath="/transport/settings";n.emailEnabled=true;n.inApp=false;n.dedupeKey=hash("test:"+UUID.randomUUID());notifications.saveAndFlush(n);return describe(n,true);}
 record Delivery(Long id,String address,String subject,String body,String company,String registration,String reference,String path,String invitationLink){}
 private Delivery claim(Long id){return tx.execute(status->{var found=notifications.lock(id);if(found.isEmpty())return null;TransportNotification n=found.get();Instant now=Instant.now();if(!policyService.policy().emailEnabled&&!"SMTP_TEST".equals(n.eventType))return null;if(n.recipient!=null&&(!Boolean.TRUE.equals(n.recipient.getEnabled())||n.recipient.getEmployee()!=null&&Boolean.FALSE.equals(n.recipient.getEmployee().getActive()))){n.deliveryStatus="CANCELLED";n.lastError="Recipient account is inactive";return null;}if(n.recipient!=null&&!Set.of("SMTP_TEST","DRIVER_INVITATION").contains(n.eventType)){var preference=drivers.findByAccount_Id(n.recipient.getId());if(preference.isPresent()&&(!preference.get().active||!preference.get().notificationsEnabled)){n.deliveryStatus="CANCELLED";n.lastError="Driver notifications are disabled";return null;}}if(!n.emailEnabled||n.attempts>=5||!(Set.of("PENDING","RETRY").contains(n.deliveryStatus)&&!n.nextAttemptAt.isAfter(now)||"SENDING".equals(n.deliveryStatus)&&n.leaseUntil!=null&&n.leaseUntil.isBefore(now)))return null;n.deliveryStatus="SENDING";n.attempts++;n.leaseUntil=now.plusSeconds(300);String invitation=null;
   if("DRIVER_INVITATION".equals(n.eventType)){if(n.recipient==null||!Boolean.TRUE.equals(n.recipient.getEnabled())){n.deliveryStatus="CANCELLED";return null;}User user=n.recipient;if(user.getPasswordResetToken()==null||user.getPasswordResetExpiresAt()==null||user.getPasswordResetExpiresAt().isBefore(LocalDateTime.now().plusMinutes(5)))accounts.requestPasswordReset(user.getEmail());invitation=frontend.replaceAll("/$","")+"/#/reset-password?token="+user.getPasswordResetToken();}
   return new Delivery(n.id,n.email,n.title,n.body,policyService.policy().companyName,n.vehicle==null?null:n.vehicle.getDvla(),n.reference,n.targetPath,invitation);
  });}
 @Scheduled(fixedDelayString="${app.transport.mail-poll-ms:30000}")
 public void deliverPending(){List<Long> ids=tx.execute(status->notifications.due(Instant.now(),policyService.policy().emailEnabled,PageRequest.of(0,25)).stream().map(n->n.id).toList());if(ids==null)return;for(Long id:ids){Delivery d=claim(id);if(d==null)continue;String error=null;try{JavaMailSender outbound=boundedSender();var message=outbound.createMimeMessage();var helper=new MimeMessageHelper(message,true,"UTF-8");helper.setTo(d.address);helper.setFrom(sender,d.company);helper.setSubject(d.subject);String target=d.invitationLink!=null?d.invitationLink:frontend.replaceAll("/$","")+"/#"+Objects.toString(d.path,"/transport/notifications");if(!target.startsWith("https://")&&!target.startsWith("http://"))throw new IllegalStateException("Invalid frontend link");String html="<html><body style='margin:0;background:#faf8f5;font-family:Arial,sans-serif;color:#28231f'><main style='max-width:600px;margin:24px auto;background:white;border:1px solid #e8e1d9;border-top:4px solid #b84b00;padding:28px'><p style='color:#b84b00;font-size:12px'>"+html(d.company)+"</p><h2>"+html(d.subject)+"</h2><p>"+html(d.body).replace("\n","<br>")+"</p>"+(d.registration==null?"":"<p>Vehicle: <strong>"+html(d.registration)+"</strong></p>")+(d.reference==null?"":"<p>Reference: "+html(d.reference)+"</p>")+"<p><a href='"+html(target)+"' style='display:inline-block;background:#b84b00;color:white;text-decoration:none;padding:12px 18px;border-radius:6px'>"+(d.invitationLink==null?"Open Transport":"Set up your password")+"</a></p><p style='font-size:12px;color:#766d64'>EAC Transport Management</p></main></body></html>";helper.setText(html,true);message.setHeader("Message-ID","<eac-transport-"+d.id+"@eac.local>");outbound.send(message);}catch(Exception e){error=e.getClass().getSimpleName()+": delivery failed; check the configured email service";}String result=error;tx.executeWithoutResult(status->{TransportNotification n=notifications.lock(id).orElseThrow();n.leaseUntil=null;if(result==null){n.deliveryStatus="DELIVERED";n.deliveredAt=Instant.now();n.lastError=null;}else{n.lastError=result;n.deliveryStatus=n.attempts>=5?"FAILED":"RETRY";n.nextAttemptAt=Instant.now().plusSeconds(Math.min(3600,30L*(1L<<Math.min(n.attempts,6))));}});}}
}
